require_once __DIR__.'/../app/layout.php';if(current_user())redirect('index.php');$error='';$role=($_GET['role']??'')==='company'?'company':'candidate';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');$role=in_array($_POST['role']??'',['candidate','company'],true)?$_POST['role']:'candidate';if(mb_strlen($name)<3||!$email||strlen($pass)<8)$error='Isi nama dan email dengan benar. Kata sandi minimal 8 karakter.';else{try{$st=db()->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);$id=(int)db()->lastInsertId();if($role==='candidate')db()->prepare('INSERT INTO candidate_profiles(user_id) VALUES(?)')->execute([$id]);else db()->prepare('INSERT INTO company_profiles(user_id,company_name) VALUES(?,?)')->execute([$id,$name]);session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>$role];flash('success','Akun berhasil dibuat. Lengkapi profil untuk memulai.');redirect($role==='company'?'company/dashboard.php':'candidate/dashboard.php');}catch(PDOException $e){$error='Email sudah digunakan atau pendaftaran belum dapat diproses.';}}}
page_header('Daftar akun'); ?>
<section class="auth"><div class="auth-card wide"><a class="brand" href="<?=e(url())?>"><span class="logo">K</span><span>Kerja<span>Setara</span><small>Karier inklusif untuk semua</small></span></a><h1>Buka peluang barumu</h1><p class="muted">Buat akun gratis untuk memulai.</p><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post" class="form"><?=csrf_field()?><label>Nama lengkap / nama perusahaan<input name="name" required minlength="3" autocomplete="name" value="<?=e($_POST['name']??'')?>"></label><label>Email aktif<input type="email" name="email" required autocomplete="email" value="<?=e($_POST['email']??'')?>"></label><label>Kata sandi (minimal 8 karakter)<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>Daftar sebagai<select name="role"><option value="candidate" <?=$role==='candidate'?'selected':''?>>Pencari kerja</option><option value="company" <?=$role==='company'?'selected':''?>>Perusahaan / perekrut</option></select></label><button class="btn btn-primary full">Buat akun</button></form><p class="auth-switch">Sudah punya akun? <a href="<?=e(url('login.php'))?>">Masuk</a></p></div></section>
